import { join } from 'node:path';

import { createTempTree, type TempTree } from '@williamthorsen/toolbelt.testing/candidate';
import { disposeOnTestFinished } from '@williamthorsen/toolbelt.vitest/candidate';
import { beforeEach, describe, expect, it } from 'vitest';

import { parseChangelogSections, planPreservedSections, readChangelogSections } from '../readChangelogSections.ts';
import type { ChangelogEntry } from '../types.ts';

const FOOTER =
  '<!-- Generated by release-kit. Do not edit this file. Use .meta/changelog-overrides.json to override entries. -->';

describe(parseChangelogSections, () => {
  it.each([
    ['## 12.0.0 — 2026-09-23', '12.0.0'],
    ['## 1.3.0', '1.3.0'],
    ['## [1.2.3] - 2024-01-01', '1.2.3'],
    ['## v1.2.3', '1.2.3'],
    ['## [v2.0.0-beta.1](https://example.com/compare/v1.0.0...v2.0.0-beta.1) (2024-01-01)', '2.0.0-beta.1'],
  ])('reads the version from %j', (heading, version) => {
    const { versionedSections } = parseChangelogSections(`${heading}\n\n- item\n`);

    expect(versionedSections).toStrictEqual([{ version, text: `${heading}\n\n- item` }]);
  });

  it('excludes the header above the first section and the footer comment', () => {
    const content = ['# Changelog', '', 'Intro.', '', '## 1.0.0', '', '- item', '', FOOTER, ''].join('\n');

    const { versionedSections, unversionedHeadings } = parseChangelogSections(content);

    expect(versionedSections).toStrictEqual([{ version: '1.0.0', text: '## 1.0.0\n\n- item' }]);
    expect(unversionedHeadings).toStrictEqual([]);
  });

  it('recognizes an earlier wording of the footer comment', () => {
    const content = '## 1.0.0\n\n- item\n\n<!-- Generated by release-kit. Use .changelog-overrides.json. -->\n';

    expect(parseChangelogSections(content).versionedSections).toStrictEqual([
      { version: '1.0.0', text: '## 1.0.0\n\n- item' },
    ]);
  });

  it('keeps deeper headings and internal formatting inside the enclosing section', () => {
    const text = [
      '## 2.0.0',
      '',
      '### Features',
      '',
      '- one',
      '',
      '  indented body',
      '',
      '#### Detail',
      '',
      'Prose.',
    ].join('\n');

    const { versionedSections } = parseChangelogSections(`${text}\n\n\n## 1.0.0\n\n- item\n`);

    expect(versionedSections).toStrictEqual([
      { version: '2.0.0', text },
      { version: '1.0.0', text: '## 1.0.0\n\n- item' },
    ]);
  });

  it('treats a `##` line inside a fenced code block as section content', () => {
    const text = ['## 1.0.0', '', '```md', '## 0.9.0', '```'].join('\n');

    expect(parseChangelogSections(`${text}\n`).versionedSections).toStrictEqual([{ version: '1.0.0', text }]);
  });

  it('reports sections without a version by heading and excludes them from the versioned list', () => {
    const content = ['## Unreleased', '', '- pending', '', '## 1.0.0', '', '- item', '', '## Notes', '', 'x'].join(
      '\n',
    );

    const { versionedSections, unversionedHeadings } = parseChangelogSections(content);

    expect(versionedSections.map((section) => section.version)).toStrictEqual(['1.0.0']);
    expect(unversionedHeadings).toStrictEqual(['## Unreleased', '## Notes']);
  });

  it('reads a version-like token in a non-release heading as a version', () => {
    const { versionedSections } = parseChangelogSections('## Upgrading from 2.0.0\n\nSteps.\n');

    expect(versionedSections.map((section) => section.version)).toStrictEqual(['2.0.0']);
  });

  it('does not read a version from a longer dotted number or a date', () => {
    const { versionedSections, unversionedHeadings } = parseChangelogSections('## Build 1.2.3.4\n\n## 2024-01-01\n');

    expect(versionedSections).toStrictEqual([]);
    expect(unversionedHeadings).toStrictEqual(['## Build 1.2.3.4', '## 2024-01-01']);
  });
});

describe(planPreservedSections, () => {
  let tree: TempTree;

  beforeEach(() => {
    tree = disposeOnTestFinished(createTempTree({}, { prefix: 'plan-preserved-sections-' }));
  });

  it('keeps hand-written sections from archive files without reporting them as dropped', () => {
    tree.write('CHANGELOG.md', ['# Changelog', '', '## 3.0.0', '', '- three', '', FOOTER, ''].join('\n'));
    tree.write(
      'changelogs/CHANGELOG-v1.md',
      ['# Changelog', '', '## 1.0.0', '', '- hand-written', '', FOOTER, ''].join('\n'),
    );

    const { sections, preservation } = planPreservedSections(tree.dir, [makeEntry('3.0.0')]);

    expect(sections).toStrictEqual([{ version: '1.0.0', text: '## 1.0.0\n\n- hand-written' }]);
    expect(preservation).toStrictEqual({
      file: join(tree.dir, 'CHANGELOG.md'),
      preservedVersions: ['1.0.0'],
      droppedUnversionedHeadings: [],
    });
  });

  it('does not preserve a version that the entries contain, from any file', () => {
    tree.write('changelogs/CHANGELOG-v2.md', '# Changelog\n\n## 2.0.0\n\n- old text\n');

    expect(planPreservedSections(tree.dir, [makeEntry('2.0.0')])).toStrictEqual({
      sections: [],
      preservation: undefined,
    });
  });

  it('takes a version found in several files from CHANGELOG.md first, then the newest archive', () => {
    tree.write('CHANGELOG.md', '# Changelog\n\n## 1.0.0\n\n- main\n');
    tree.write('changelogs/CHANGELOG-v1.md', '# Changelog\n\n## 1.0.0\n\n- archive\n\n## 0.2.0\n\n- one\n');
    tree.write('changelogs/CHANGELOG-v0.md', '# Changelog\n\n## 0.2.0\n\n- zero\n');

    const { sections } = planPreservedSections(tree.dir, []);

    expect(sections).toStrictEqual([
      { version: '1.0.0', text: '## 1.0.0\n\n- main' },
      { version: '0.2.0', text: '## 0.2.0\n\n- one' },
    ]);
  });

  it('reports unversioned headings found in an archive file as dropped', () => {
    tree.write('changelogs/CHANGELOG-v1.md', '# Changelog\n\n## Unreleased\n\n- pending\n');

    expect(planPreservedSections(tree.dir, []).preservation?.droppedUnversionedHeadings).toStrictEqual([
      '## Unreleased',
    ]);
  });

  it('ignores files in the archive directory whose names do not match the archive pattern', () => {
    tree.write('changelogs/NOTES.md', '# Notes\n\n## 1.0.0\n\n- not an archive\n');

    expect(planPreservedSections(tree.dir, [])).toStrictEqual({ sections: [], preservation: undefined });
  });
});

describe(readChangelogSections, () => {
  let tree: TempTree;

  beforeEach(() => {
    tree = disposeOnTestFinished(createTempTree({}, { prefix: 'read-changelog-sections-' }));
  });

  it('returns empty lists for a missing file', () => {
    expect(readChangelogSections(join(tree.dir, 'CHANGELOG.md'))).toStrictEqual({
      versionedSections: [],
      unversionedHeadings: [],
    });
  });

  it('reads the sections of an existing file', () => {
    const filePath = tree.write('CHANGELOG.md', '# Changelog\n\n## 1.0.0\n\n- item\n');

    expect(readChangelogSections(filePath).versionedSections).toStrictEqual([
      { version: '1.0.0', text: '## 1.0.0\n\n- item' },
    ]);
  });
});

// region | Helpers

/** Builds an entry for `version` that does not have any sections. */
function makeEntry(version: string): ChangelogEntry {
  return { version, date: '2024-01-01', sections: [] };
}

// endregion | Helpers
